import {Engine,sources,symbols,createGenerator} from './engine.js';
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let engine=new Engine(),generate=createGenerator(),running=false,timers=[],socket=null,firstAt=null,activeMs=0,startedAt=null,counts={atlas:0,beacon:0,cobalt:0};
const price=v=>v.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
$('sources').innerHTML=sources.map((s,i)=>`<div class="source"><label>${s}<input id="enable-${s}" type="checkbox" checked aria-label="Enable ${s}"></label><div class="source-info"><span>${['Canonical JSON','String values','Alternate keys'][i]}</span><span id="count-${s}">0 ticks</span></div></div>`).join('');
function accept(source,raw){const tick=engine.ingest(source,raw);if(tick){counts[source]++;if(firstAt===null)firstAt=performance.now();}return tick;}
function stop(){timers.forEach(clearInterval);timers=[];if(startedAt!==null){activeMs+=performance.now()-startedAt;startedAt=null;}running=false;$('play').textContent='Start streams';}
function disconnect(){if(socket){socket.onclose=null;socket.close();socket=null;}$('connection').textContent='Browser simulation mode';$('connect').textContent='Connect same-origin Python stream';sources.forEach(s=>$('enable-'+s).disabled=false);$('speed').disabled=false;}
function start(){disconnect();stop();running=true;startedAt=performance.now();$('play').textContent='Pause streams';sources.forEach((s,i)=>{if($('enable-'+s).checked)timers.push(setInterval(()=>accept(s,generate(s)),[160,230,310][i]/Number($('speed').value)));});$('message').textContent='Streaming synthetic data from enabled browser sources.';}
function reset(){stop();disconnect();engine=new Engine();generate=createGenerator();firstAt=null;activeMs=0;counts={atlas:0,beacon:0,cobalt:0};$('message').textContent='Session reset. Ready to start.';render();}
$('play').onclick=()=>{if(running){stop();$('message').textContent='Paused. Current data is retained.';}else start();};$('reset').onclick=reset;$('speed').onchange=()=>{if(running)start();};sources.forEach(s=>$('enable-'+s).onchange=()=>{if(running)start();});
$('symbol').onchange=$('filter').onchange=render;
$('bad').onclick=()=>{accept('atlas',{id:'bad-'+Date.now(),symbol:'BTC-USD',price:-1,size:1,timestamp:Date.now()});$('fault-status').textContent='Invalid price sent; record rejected.';render();};
$('duplicate').onclick=()=>{const last=engine.records.at(-1);if(!last){$('fault-status').textContent='Start a stream first.';return;}accept(last.source,last);$('fault-status').textContent='Last source + ID repeated; duplicate skipped.';render();};
$('late').onclick=()=>{const last=engine.records.at(-1);if(!last){$('fault-status').textContent='Start a stream first.';return;}accept(last.source,{...last,id:'late-'+crypto.randomUUID(),timestamp:last.timestamp-60000});$('fault-status').textContent='Late tick retained; newest quote preserved.';render();};
function render(){const stats=engine.stats;$('accepted').textContent=stats.accepted.toLocaleString();const elapsed=activeMs+(startedAt===null?0:performance.now()-startedAt);$('rate').innerHTML=(elapsed?Math.round(stats.accepted/(elapsed/1000)):0)+' <small>ticks/s</small>';const sorted=[...engine.processing].sort((a,b)=>a-b);$('latency').textContent=sorted.length?sorted[Math.min(sorted.length-1,Math.floor(sorted.length*.95))].toFixed(3)+' ms':'—';$('flags').textContent=stats.rejected+stats.duplicates+stats.out_of_order;for(const k of ['rejected','duplicates','out_of_order'])$(k).textContent=stats[k];sources.forEach(s=>$('count-'+s).textContent=counts[s]+' ticks');
const symbol=$('symbol').value,quote=engine.quote(symbol);$('price').textContent=quote?'$'+price(quote.price):'—';$('quote-meta').textContent=quote?quote.source+' · event '+new Date(quote.timestamp).toLocaleTimeString():'Waiting for the first tick';
$('quotes').innerHTML=symbols.map(s=>{const q=engine.quote(s);return `<button class="quote-card ${s===symbol?'active':''}" data-symbol="${s}"><span>${s}</span><strong>${q?'$'+price(q.price):'—'}</strong></button>`;}).join('');$('quotes').querySelectorAll('button').forEach(b=>b.onclick=()=>{$('symbol').value=b.dataset.symbol;render();});
const points=engine.records.filter(t=>t.symbol===symbol).slice(-120).sort((a,b)=>a.timestamp-b.timestamp);$('chart-empty').style.display=points.length?'none':'flex';let chart='';for(let i=0;i<4;i++){const y=20+i*55;chart+=`<line x1="0" y1="${y}" x2="800" y2="${y}" stroke="#273547" stroke-dasharray="3 5"/>`;}
if(points.length){const values=points.map(t=>t.price),low=Math.min(...values),high=Math.max(...values),span=high-low||Math.max(1,high*.001),t0=points[0].timestamp,t1=points.at(-1).timestamp;const xy=points.map((t,i)=>[t1===t0?i/Math.max(1,points.length-1)*700+45:45+(t.timestamp-t0)/(t1-t0)*700,175-(t.price-low)/span*135]);chart+=`<polyline points="${xy.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#65dec4" stroke-width="2"/><circle cx="${xy.at(-1)[0]}" cy="${xy.at(-1)[1]}" r="4" fill="#65dec4"/><text x="6" y="14" fill="#9aa8bb" font-size="12">${price(high)}</text><text x="6" y="202" fill="#9aa8bb" font-size="12">${price(low)}</text>`;}$('chart').innerHTML=chart;
const rows=engine.records.filter(t=>t.symbol===symbol&&($('filter').value==='all'||t.source===$('filter').value)).slice(-12).reverse();$('ticks').innerHTML=rows.length?rows.map(t=>`<tr><td>${new Date(t.timestamp).toLocaleTimeString()}</td><td><span class="source-pill">${esc(t.source)}</span></td><td>${esc(t.symbol)}</td><td>${price(t.price)}</td><td>${t.size.toFixed(3)}</td></tr>`).join(''):'<tr><td colspan="5">No matching ticks yet.</td></tr>';$('issues').innerHTML=engine.issues.length?engine.issues.slice(0,4).map(i=>`${esc(i.source)} · ${esc(i.error)}`).join('<br>'):'No validation errors.';$('export').disabled=!engine.records.length;}
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(engine.records,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='tickstream-normalized.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import').onchange=async()=>{try{const f=$('import').files[0];if(!f)return;if(f.size>2*1024*1024)throw Error('Choose a file under 2 MB.');const rows=JSON.parse(await f.text());if(!Array.isArray(rows)||!rows.length||rows.length>10000)throw Error('Provide 1–10,000 normalized ticks as a JSON array.');if(rows.some(t=>!t||!sources.includes(t.source)))throw Error('Every tick needs a known source: atlas, beacon or cobalt.');reset();const begin=performance.now();rows.forEach(t=>accept(t.source,t));activeMs=performance.now()-begin;$('message').textContent=`Replayed ${rows.length} ticks. ${engine.stats.accepted} accepted; ${engine.stats.rejected} invalid; ${engine.stats.duplicates} duplicates.`;render();}catch(e){$('message').textContent=e.message;}finally{$('import').value='';}};
$('connect').onclick=()=>{if(socket){disconnect();stop();return;}stop();socket=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/stream`);const ws=socket;const timeout=setTimeout(()=>{if(ws.readyState!==WebSocket.OPEN)ws.close();},7000);$('connection').textContent='Connecting…';ws.onopen=()=>{clearTimeout(timeout);startedAt=performance.now();$('connection').textContent='Connected to Python normalized stream';$('connect').textContent='Disconnect Python stream';sources.forEach(s=>$('enable-'+s).disabled=true);$('speed').disabled=true;$('message').textContent='Receiving the Python pipeline’s local synthetic WebSocket output.';};ws.onmessage=event=>{try{const data=JSON.parse(event.data);if(data.type==='tick')accept(data.tick.source,data.tick);}catch{$('message').textContent='Received an invalid WebSocket message.';}};ws.onerror=()=>{$('connection').textContent='Python stream unavailable here. Use Start streams for the hosted browser demo.';};ws.onclose=()=>{clearTimeout(timeout);if(socket===ws){stop();disconnect();$('connection').textContent='Python connection closed. Browser simulation is available.';}};};
setInterval(render,250);render();
